// ═══════════════════════════════════════════════════════════════
// EMA RIBBON (4-LAYER) — Quant Prime Free Module
// Paste this entire block into your indicator.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
ema_show    = input.bool(true, "Show EMA Ribbon", group="EMA Ribbon")
ema1_len    = input.int(8,   "Fast EMA",   group="EMA Ribbon")
ema2_len    = input.int(26,  "Medium EMA", group="EMA Ribbon")
ema3_len    = input.int(80,  "Slow EMA",   group="EMA Ribbon")
ema4_len    = input.int(233, "Anchor EMA", group="EMA Ribbon")
ema1_col    = input.color(#7fdbff, "Fast Color",   group="EMA Ribbon")
ema2_col    = input.color(#00abff, "Medium Color", group="EMA Ribbon")
ema3_col    = input.color(#0085c7, "Slow Color",   group="EMA Ribbon")
ema4_col    = input.color(#005e8c, "Anchor Color", group="EMA Ribbon")

// ─── CALCULATIONS ─────────────────────────────────────────────
ema1 = ta.ema(close, ema1_len)
ema2 = ta.ema(close, ema2_len)
ema3 = ta.ema(close, ema3_len)
ema4 = ta.ema(close, ema4_len)

// Trend detection: EMAs stacked in order
ema_bull = ema1 > ema2 and ema2 > ema3 and ema3 > ema4
ema_bear = ema1 < ema2 and ema2 < ema3 and ema3 < ema4
ema_bias = ema_bull ? "BULL" : ema_bear ? "BEAR" : "FLAT"

// ─── PLOTTING ─────────────────────────────────────────────────
plot(ema_show ? ema1 : na, "EMA Fast",   color=ema1_col, linewidth=1)
plot(ema_show ? ema2 : na, "EMA Medium", color=ema2_col, linewidth=1)
plot(ema_show ? ema3 : na, "EMA Slow",   color=ema3_col, linewidth=1)
plot(ema_show ? ema4 : na, "EMA Anchor", color=ema4_col, linewidth=2)

// ─── USAGE ────────────────────────────────────────────────────
// Access ema_bias anywhere: "BULL", "BEAR", or "FLAT"
// Example: if ema_bias == "BULL" and your_signal
//              strategy.entry("Long", strategy.long)

// ═══════════════════════════════════════════════════════════════
// PREVIOUS DAY HIGH/LOW/CLOSE — Quant Prime Free Module
// Paste this entire block into your indicator.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
pdhl_show   = input.bool(true, "Show PDH/PDL/PDC", group="Previous Day Levels")
pdh_col     = input.color(#26a269, "PDH Color", group="Previous Day Levels")
pdl_col     = input.color(#f23645, "PDL Color", group="Previous Day Levels")
pdc_col     = input.color(#888888, "PDC Color", group="Previous Day Levels")
pdhl_style  = input.string("Solid", "Line Style", options=["Solid", "Dashed", "Dotted"], group="Previous Day Levels")

// ─── CALCULATIONS ─────────────────────────────────────────────
[pd_high, pd_low, pd_close] = request.security(syminfo.tickerid, "D", [high[1], low[1], close[1]], lookahead=barmerge.lookahead_on)

// Line style conversion
ls = pdhl_style == "Dashed" ? line.style_dashed : pdhl_style == "Dotted" ? line.style_dotted : line.style_solid

// ─── PLOTTING ─────────────────────────────────────────────────
plot(pdhl_show ? pd_high  : na, "PDH", color=pdh_col, linewidth=1, style=plot.style_linebr)
plot(pdhl_show ? pd_low   : na, "PDL", color=pdl_col, linewidth=1, style=plot.style_linebr)
plot(pdhl_show ? pd_close : na, "PDC", color=pdc_col, linewidth=1, style=plot.style_linebr)

// ─── USAGE ────────────────────────────────────────────────────
// Check if price is above/below key levels:
// above_pdh = close > pd_high
// below_pdl = close < pd_low
// Use for breakout confirmation or S/R bounce trades.

// ═══════════════════════════════════════════════════════════════
// WEEKLY OPEN LINE — Quant Prime Free Module
// Paste this entire block into your indicator.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
wo_show     = input.bool(true, "Show Weekly Open", group="Weekly Open")
wo_col      = input.color(#c9a84c, "Line Color", group="Weekly Open")
wo_width    = input.int(2, "Line Width", minval=1, maxval=4, group="Weekly Open")
wo_extend   = input.bool(true, "Extend Line", group="Weekly Open")

// ─── CALCULATIONS ─────────────────────────────────────────────
weekly_open = request.security(syminfo.tickerid, "W", open, lookahead=barmerge.lookahead_on)

// Bias: above weekly open = bullish week, below = bearish
weekly_bias = close > weekly_open ? "BULL" : close < weekly_open ? "BEAR" : "NEUTRAL"

// ─── PLOTTING ─────────────────────────────────────────────────
plot(wo_show ? weekly_open : na, "Weekly Open", color=wo_col, linewidth=wo_width, style=plot.style_linebr)

// Optional: color background based on bias
// bgcolor(weekly_bias == "BULL" ? color.new(#26a269, 95) : weekly_bias == "BEAR" ? color.new(#f23645, 95) : na)

// ─── USAGE ────────────────────────────────────────────────────
// Access weekly_bias: "BULL", "BEAR", or "NEUTRAL"
// Institutions often use weekly open as a reference point.
// Longs above WO, shorts below WO increases probability.

// ═══════════════════════════════════════════════════════════════
// CANDLE COUNTDOWN TIMER — Quant Prime Free Module
// Paste this entire block into your indicator.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
cd_show     = input.bool(true, "Show Countdown", group="Countdown Timer")
cd_pos      = input.string("Top Right", "Position", options=["Top Right", "Top Left", "Bottom Right", "Bottom Left"], group="Countdown Timer")
cd_size     = input.string("Normal", "Size", options=["Tiny", "Small", "Normal", "Large"], group="Countdown Timer")
cd_col      = input.color(#c9a84c, "Text Color", group="Countdown Timer")

// ─── CALCULATIONS ─────────────────────────────────────────────
// Get timeframe in milliseconds
tf_ms = timeframe.in_seconds() * 1000

// Time elapsed since candle open
elapsed = time_close - time
remaining = tf_ms - (timenow - time)

// Convert to minutes and seconds
mins = math.floor(remaining / 60000)
secs = math.floor((remaining % 60000) / 1000)

// Format string
cd_text = str.format("{0,number,00}:{1,number,00}", mins, secs)

// Position mapping
pos_y = str.contains(cd_pos, "Top") ? yloc.abovebar : yloc.belowbar
pos_x = str.contains(cd_pos, "Right") ? label.style_label_left : label.style_label_right
size_map = cd_size == "Tiny" ? size.tiny : cd_size == "Small" ? size.small : cd_size == "Large" ? size.large : size.normal

// ─── PLOTTING ─────────────────────────────────────────────────
var label cd_label = na
if cd_show and barstate.islast
    label.delete(cd_label)
    cd_label := label.new(bar_index, close, cd_text, xloc.bar_index, pos_y, cd_col, pos_x, cd_col, size_map)

// ─── USAGE ────────────────────────────────────────────────────
// The countdown updates live on the current candle.
// Useful for timing entries before candle close confirmation.

// ═══════════════════════════════════════════════════════════════
// SESSION HIGHLIGHTER — Quant Prime Free Module
// Paste this entire block into your indicator.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
show_london  = input.bool(true, "Show London",  group="Sessions")
show_ny      = input.bool(true, "Show New York", group="Sessions")
show_tokyo   = input.bool(true, "Show Tokyo",   group="Sessions")
show_sydney  = input.bool(true, "Show Sydney",  group="Sessions")

london_col   = input.color(color.new(#00abff, 90), "London Color",   group="Sessions")
ny_col       = input.color(color.new(#26a269, 90), "New York Color", group="Sessions")
tokyo_col    = input.color(color.new(#c9a84c, 90), "Tokyo Color",    group="Sessions")
sydney_col   = input.color(color.new(#8b5cf6, 90), "Sydney Color",   group="Sessions")

// Session times (in exchange timezone, adjust as needed)
london_start = input.session("0800-1600", "London Hours", group="Sessions")
ny_start     = input.session("1300-2100", "New York Hours", group="Sessions")
tokyo_start  = input.session("0000-0800", "Tokyo Hours", group="Sessions")
sydney_start = input.session("2100-0500", "Sydney Hours", group="Sessions")

// ─── CALCULATIONS ─────────────────────────────────────────────
is_london = not na(time(timeframe.period, london_start))
is_ny     = not na(time(timeframe.period, ny_start))
is_tokyo  = not na(time(timeframe.period, tokyo_start))
is_sydney = not na(time(timeframe.period, sydney_start))

// Current session name
current_session = is_london ? "LONDON" : is_ny ? "NEW YORK" : is_tokyo ? "TOKYO" : is_sydney ? "SYDNEY" : "OFF-SESSION"

// ─── PLOTTING ─────────────────────────────────────────────────
bgcolor(show_london and is_london ? london_col : na, title="London BG")
bgcolor(show_ny and is_ny ? ny_col : na, title="New York BG")
bgcolor(show_tokyo and is_tokyo ? tokyo_col : na, title="Tokyo BG")
bgcolor(show_sydney and is_sydney ? sydney_col : na, title="Sydney BG")

// ─── USAGE ────────────────────────────────────────────────────
// Access current_session variable for logic:
// if current_session == "LONDON" and your_signal
//     // Take London session trades only

// ═══════════════════════════════════════════════════════════════
// WEEKLY ANALYSIS TEMPLATE — Quant Prime Research Module
// Use this as a framework for your weekly prep.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
show_analysis = input.bool(true, "Show Analysis Panel", group="Weekly Analysis")

// Manual key level inputs (update weekly)
key_res_1    = input.price(0.0, "Resistance 1", group="Key Levels")
key_res_2    = input.price(0.0, "Resistance 2", group="Key Levels")
key_sup_1    = input.price(0.0, "Support 1", group="Key Levels")
key_sup_2    = input.price(0.0, "Support 2", group="Key Levels")

// Weekly bias input
weekly_bias_input = input.string("Neutral", "Weekly Bias", options=["Bullish", "Bearish", "Neutral"], group="Weekly Analysis")

// ─── HTF BIAS CALCULATION ─────────────────────────────────────
[d1_close, d1_ema50] = request.security(syminfo.tickerid, "D", [close, ta.ema(close, 50)])
[w1_close, w1_ema20] = request.security(syminfo.tickerid, "W", [close, ta.ema(close, 20)])

d1_bias = d1_close > d1_ema50 ? "BULL" : "BEAR"
w1_bias = w1_close > w1_ema20 ? "BULL" : "BEAR"
htf_aligned = d1_bias == w1_bias

// ─── PLOTTING KEY LEVELS ──────────────────────────────────────
plot(key_res_1 > 0 ? key_res_1 : na, "Res 1", color=#f23645, linewidth=2, style=plot.style_linebr)
plot(key_res_2 > 0 ? key_res_2 : na, "Res 2", color=#f23645, linewidth=1, style=plot.style_linebr)
plot(key_sup_1 > 0 ? key_sup_1 : na, "Sup 1", color=#26a269, linewidth=2, style=plot.style_linebr)
plot(key_sup_2 > 0 ? key_sup_2 : na, "Sup 2", color=#26a269, linewidth=1, style=plot.style_linebr)

// ─── ANALYSIS DASHBOARD ───────────────────────────────────────
var table analysis_tbl = table.new(position.top_right, 2, 6, bgcolor=#1a1a1a, border_width=1)
if show_analysis and barstate.islast
    table.cell(analysis_tbl, 0, 0, "WEEKLY ANALYSIS", text_color=#c9a84c, text_size=size.small)
    table.cell(analysis_tbl, 0, 1, "D1 Bias:", text_color=#888)
    table.cell(analysis_tbl, 1, 1, d1_bias, text_color=d1_bias=="BULL"?#26a269:#f23645)
    table.cell(analysis_tbl, 0, 2, "W1 Bias:", text_color=#888)
    table.cell(analysis_tbl, 1, 2, w1_bias, text_color=w1_bias=="BULL"?#26a269:#f23645)
    table.cell(analysis_tbl, 0, 3, "HTF Aligned:", text_color=#888)
    table.cell(analysis_tbl, 1, 3, htf_aligned?"YES":"NO", text_color=htf_aligned?#26a269:#f23645)

// ═══════════════════════════════════════════════════════════════
// VOLATILITY REPORT GENERATOR — Quant Prime Research Module
// Shows current volatility state and expansion probability.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
vol_show     = input.bool(true, "Show Volatility Panel", group="Volatility Report")
atr_fast     = input.int(14, "Fast ATR", group="Volatility Report")
atr_slow     = input.int(50, "Slow ATR", group="Volatility Report")
vol_high_th  = input.float(1.2, "High Vol Threshold", step=0.1, group="Volatility Report")
vol_low_th   = input.float(0.8, "Low Vol Threshold", step=0.1, group="Volatility Report")

// ─── CALCULATIONS ─────────────────────────────────────────────
atr_14 = ta.atr(atr_fast)
atr_50 = ta.atr(atr_slow)
atr_ratio = atr_14 / atr_50

// Volatility state
vol_state = atr_ratio > vol_high_th ? "HIGH" : atr_ratio < vol_low_th ? "LOW" : "NORMAL"

// Compression detection (low vol = potential expansion coming)
is_compressed = atr_ratio < vol_low_th
compression_bars = ta.barssince(atr_ratio >= vol_low_th)

// Historical percentile (where is current vol vs last 100 bars)
atr_percentile = ta.percentrank(atr_14, 100)

// ─── DASHBOARD ────────────────────────────────────────────────
var table vol_tbl = table.new(position.top_right, 2, 5, bgcolor=#1a1a1a, border_width=1)
if vol_show and barstate.islast
    state_col = vol_state=="HIGH"?#f23645 : vol_state=="LOW"?#00abff : #888
    table.cell(vol_tbl, 0, 0, "VOLATILITY", text_color=#c9a84c, text_size=size.small)
    table.cell(vol_tbl, 0, 1, "State:", text_color=#888)
    table.cell(vol_tbl, 1, 1, vol_state, text_color=state_col)
    table.cell(vol_tbl, 0, 2, "ATR Ratio:", text_color=#888)
    table.cell(vol_tbl, 1, 2, str.tostring(atr_ratio, "#.##"), text_color=#fff)
    table.cell(vol_tbl, 0, 3, "Percentile:", text_color=#888)
    table.cell(vol_tbl, 1, 3, str.tostring(atr_percentile, "#") + "%", text_color=#fff)
    table.cell(vol_tbl, 0, 4, "Compressed:", text_color=#888)
    table.cell(vol_tbl, 1, 4, is_compressed ? str.tostring(compression_bars) + " bars" : "No", text_color=is_compressed?#00abff:#888)

// ─── USAGE ────────────────────────────────────────────────────
// vol_state: "HIGH", "LOW", or "NORMAL"
// is_compressed: true when volatility is contracted (expansion likely)
// Use compression_bars to see how long compression has lasted

// ═══════════════════════════════════════════════════════════════
// VOLATILITY BAND SYSTEM — Quant Prime Recoil Module
// 8-band ATR classification. Core of the Recoil fade engine.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
atr_len      = input.int(8, "ATR Length", group="Volatility Bands")
color_candles = input.bool(true, "Color Candles", group="Volatility Bands")

// Thresholds (ATR ratio boundaries)
th1 = input.float(0.30, "Band 1→2", group="Thresholds", step=0.05)
th2 = input.float(0.75, "Band 2→3", group="Thresholds", step=0.05)
th3 = input.float(1.20, "Band 3→4", group="Thresholds", step=0.05)
th4 = input.float(1.65, "Band 4→5", group="Thresholds", step=0.05)
th5 = input.float(2.10, "Band 5→6 (TRIGGER)", group="Thresholds", step=0.05)
th6 = input.float(2.55, "Band 6→7", group="Thresholds", step=0.05)
th7 = input.float(3.00, "Band 7→8", group="Thresholds", step=0.05)

// Colors
col1 = input.color(#1e1e28, "Band 1", group="Colors")
col2 = input.color(#2a2a36, "Band 2", group="Colors")
col3 = input.color(#363644, "Band 3", group="Colors")
col4 = input.color(#424252, "Band 4", group="Colors")
col5 = input.color(#4e4e60, "Band 5", group="Colors")
col6 = input.color(#e6a830, "Band 6 (Trigger 1x)", group="Colors")
col7 = input.color(#c9a84c, "Band 7 (Trigger 2x)", group="Colors")
col8 = input.color(#f23645, "Band 8 (Trigger 5x)", group="Colors")

// ─── CALCULATIONS ─────────────────────────────────────────────
atr_val = ta.atr(atr_len)
true_range = ta.tr
ratio = true_range / atr_val

// Band classification
vol_band = ratio > th7 ? 8 : ratio > th6 ? 7 : ratio > th5 ? 6 :
           ratio > th4 ? 5 : ratio > th3 ? 4 : ratio > th2 ? 3 :
           ratio > th1 ? 2 : 1

// Is this a trigger candle?
is_trigger = vol_band >= 6
trigger_mult = vol_band == 8 ? 5.0 : vol_band == 7 ? 2.0 : vol_band == 6 ? 1.0 : 0.0

// Candle direction
is_bullish = close > open
is_bearish = close < open

// Fade direction (opposite of candle)
fade_direction = is_trigger ? (is_bullish ? -1 : is_bearish ? 1 : 0) : 0

// ─── CANDLE COLORING ──────────────────────────────────────────
band_color = vol_band == 8 ? col8 : vol_band == 7 ? col7 : vol_band == 6 ? col6 :
             vol_band == 5 ? col5 : vol_band == 4 ? col4 : vol_band == 3 ? col3 :
             vol_band == 2 ? col2 : col1

barcolor(color_candles ? band_color : na)

// ─── USAGE ────────────────────────────────────────────────────
// vol_band: 1-8 (higher = more volatile)
// is_trigger: true when band 6/7/8
// trigger_mult: 1x/2x/5x position multiplier
// fade_direction: 1 = fade to long, -1 = fade to short
//
// Example: if is_trigger and fade_direction == 1
//              strategy.entry("Fade Long", strategy.long)

// ═══════════════════════════════════════════════════════════════
// ATR STOP LOSS CALCULATOR — Quant Prime Recoil Module
// Dynamic stop placement based on volatility.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
sl_atr_len   = input.int(14, "ATR Length", group="ATR Stop")
sl_mult      = input.float(1.5, "ATR Multiplier", step=0.1, group="ATR Stop")
sl_from      = input.string("Close", "Calculate From", options=["Close", "Low/High", "Wick"], group="ATR Stop")
show_sl_line = input.bool(true, "Show SL Lines", group="ATR Stop")
sl_col       = input.color(#f23645, "SL Color", group="ATR Stop")

// ─── CALCULATIONS ─────────────────────────────────────────────
atr_sl = ta.atr(sl_atr_len)
sl_distance = atr_sl * sl_mult

// Calculate SL based on selected method
long_sl_base = sl_from == "Close" ? close : sl_from == "Low/High" ? low : low - (high - low) * 0.1
short_sl_base = sl_from == "Close" ? close : sl_from == "Low/High" ? high : high + (high - low) * 0.1

long_sl_price = long_sl_base - sl_distance
short_sl_price = short_sl_base + sl_distance

// Pip calculation (adjust divisor for your instrument)
pip_size = syminfo.mintick * 10  // Standard forex pip
long_sl_pips = sl_distance / pip_size
short_sl_pips = sl_distance / pip_size

// ─── PLOTTING ─────────────────────────────────────────────────
plot(show_sl_line ? long_sl_price : na, "Long SL", color=sl_col, style=plot.style_linebr, linewidth=1)
plot(show_sl_line ? short_sl_price : na, "Short SL", color=sl_col, style=plot.style_linebr, linewidth=1)

// ─── DASHBOARD ────────────────────────────────────────────────
var table sl_tbl = table.new(position.bottom_left, 2, 4, bgcolor=#1a1a1a, border_width=1)
if barstate.islast
    table.cell(sl_tbl, 0, 0, "ATR STOP", text_color=#c9a84c)
    table.cell(sl_tbl, 0, 1, "Long SL:", text_color=#888)
    table.cell(sl_tbl, 1, 1, str.tostring(long_sl_price, format.mintick), text_color=#f23645)
    table.cell(sl_tbl, 0, 2, "Short SL:", text_color=#888)
    table.cell(sl_tbl, 1, 2, str.tostring(short_sl_price, format.mintick), text_color=#f23645)
    table.cell(sl_tbl, 0, 3, "Distance:", text_color=#888)
    table.cell(sl_tbl, 1, 3, str.tostring(long_sl_pips, "#.#") + " pips", text_color=#fff)

// ═══════════════════════════════════════════════════════════════
// AMD PHASE ENGINE — Quant Prime Meridian Module
// Detects Accumulation, Manipulation, Distribution phases.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
amd_show     = input.bool(true, "Show AMD Phases", group="AMD Engine")
cycle_12h    = input.bool(true, "12H Cycle", group="AMD Engine")
cycle_6h     = input.bool(true, "6H Cycle", group="AMD Engine")

amd_tz       = input.string("UTC+0", "Timezone", options=["UTC-5","UTC-4","UTC+0","UTC+1","UTC+2"], group="AMD Engine")

// Colors
accum_col    = input.color(color.new(#c9a84c, 85), "Accumulation", group="AMD Colors")
manip_col    = input.color(color.new(#f23645, 85), "Manipulation", group="AMD Colors")
dist_col     = input.color(color.new(#26a269, 85), "Distribution", group="AMD Colors")

// ─── TIME CALCULATIONS ────────────────────────────────────────
// Get hour of day based on timezone offset
tz_offset = amd_tz == "UTC-5" ? -5 : amd_tz == "UTC-4" ? -4 : amd_tz == "UTC+1" ? 1 : amd_tz == "UTC+2" ? 2 : 0
hour_of_day = (hour + tz_offset + 24) % 24

// 12H cycle phases (each 4 hours)
cycle_12h_phase = cycle_12h ? (hour_of_day % 12) / 4 : na
is_12h_accum = cycle_12h and cycle_12h_phase < 1
is_12h_manip = cycle_12h and cycle_12h_phase >= 1 and cycle_12h_phase < 2
is_12h_dist = cycle_12h and cycle_12h_phase >= 2

// 6H cycle phases (each 2 hours)
cycle_6h_phase = cycle_6h ? (hour_of_day % 6) / 2 : na
is_6h_accum = cycle_6h and cycle_6h_phase < 1
is_6h_manip = cycle_6h and cycle_6h_phase >= 1 and cycle_6h_phase < 2
is_6h_dist = cycle_6h and cycle_6h_phase >= 2

// Combined phase (prioritize 12H)
current_phase = is_12h_accum or is_6h_accum ? "ACCUMULATION" :
                is_12h_manip or is_6h_manip ? "MANIPULATION" :
                is_12h_dist or is_6h_dist ? "DISTRIBUTION" : "NONE"

// ─── A-LINE DETECTION ─────────────────────────────────────────
// A-Line = first bar of new cycle (accumulation start)
is_12h_aline = cycle_12h and hour_of_day % 12 == 0 and barstate.isconfirmed[1]
is_6h_aline = cycle_6h and hour_of_day % 6 == 0 and barstate.isconfirmed[1]

var float aline_12h = na
var float aline_6h = na

if is_12h_aline
    aline_12h := high  // A-line at high of first bar
if is_6h_aline
    aline_6h := high

// ─── BACKGROUND COLORING ──────────────────────────────────────
bg_col = current_phase == "ACCUMULATION" ? accum_col :
         current_phase == "MANIPULATION" ? manip_col :
         current_phase == "DISTRIBUTION" ? dist_col : na

bgcolor(amd_show ? bg_col : na)

// ─── PLOTTING ─────────────────────────────────────────────────
plot(amd_show and cycle_12h ? aline_12h : na, "12H A-Line", color=#c9a84c, linewidth=2, style=plot.style_linebr)
plot(amd_show and cycle_6h ? aline_6h : na, "6H A-Line", color=#00abff, linewidth=1, style=plot.style_linebr)

// ─── USAGE ────────────────────────────────────────────────────
