// ═══════════════════════════════════════════════════════════════
// LIQUIDITY POOL DETECTOR — Quant Prime Cockpit Module
// Detects swing highs/lows and tracks sweeps.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
lp_show      = input.bool(true, "Show LP Levels", group="Liquidity Pools")
left_bars    = input.int(4, "Left Bars", minval=1, group="Liquidity Pools")
right_bars   = input.int(2, "Right Bars", minval=1, group="Liquidity Pools")
lp_max       = input.int(10, "Max Levels", group="Liquidity Pools")

lp_high_col  = input.color(#f23645, "High LP Color", group="Liquidity Pools")
lp_low_col   = input.color(#26a269, "Low LP Color", group="Liquidity Pools")
swept_col    = input.color(#888888, "Swept Color", group="Liquidity Pools")

// ─── PIVOT DETECTION ──────────────────────────────────────────
pivot_high = ta.pivothigh(high, left_bars, right_bars)
pivot_low = ta.pivotlow(low, left_bars, right_bars)

// ─── LP TRACKING ──────────────────────────────────────────────
type LP
    float price
    int bar_idx
    bool is_high
    bool is_swept
    line ln

var LP[] lps = array.new<LP>()

// Add new LPs
if lp_show and not na(pivot_high)
    price = pivot_high
    ln = line.new(bar_index - right_bars, price, bar_index + 50, price, color=lp_high_col, style=line.style_dashed)
    lp = LP.new(price, bar_index - right_bars, true, false, ln)
    array.push(lps, lp)

if lp_show and not na(pivot_low)
    price = pivot_low
    ln = line.new(bar_index - right_bars, price, bar_index + 50, price, color=lp_low_col, style=line.style_dashed)
    lp = LP.new(price, bar_index - right_bars, false, false, ln)
    array.push(lps, lp)

// Check for sweeps
var bool high_swept = false
var bool low_swept = false

if array.size(lps) > 0
    for i = array.size(lps) - 1 to 0
        lp = array.get(lps, i)
        if not lp.is_swept
            // High LP swept when price goes above then closes below
            if lp.is_high and high > lp.price and close < lp.price
                lp.is_swept := true
                line.set_color(lp.ln, swept_col)
                high_swept := true
            // Low LP swept when price goes below then closes above
            if not lp.is_high and low < lp.price and close > lp.price
                lp.is_swept := true
                line.set_color(lp.ln, swept_col)
                low_swept := true

        // Extend lines
        line.set_x2(lp.ln, bar_index + 10)

    // Limit array
    while array.size(lps) > lp_max
        old = array.shift(lps)
        line.delete(old.ln)

// Reset sweep flags
if high_swept[1]
    high_swept := false
if low_swept[1]
    low_swept := false

// ─── ALERTS ───────────────────────────────────────────────────
alertcondition(high_swept, "High LP Swept", "Liquidity above swing high was swept")
alertcondition(low_swept, "Low LP Swept", "Liquidity below swing low was swept")

// ─── USAGE ────────────────────────────────────────────────────
// high_swept / low_swept: true when a sweep just occurred
// Use sweeps as entry triggers (reversal after liquidity grab)

