// ═══════════════════════════════════════════════════════════════
// MT5 SIGNAL RECEIVER — Quant Prime Ascension Module (MQL5)
// Polls webhook endpoint for TradingView signals.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
input string WebhookURL = "http://your-server:3000/signals"; // Signal endpoint
input int    PollIntervalMs = 1000;  // Poll every 1 second
input string ApiKey = "";            // Optional API key

// ─── SIGNAL STRUCTURE ─────────────────────────────────────────
struct Signal {
    string symbol;
    string action;     // BUY, SELL, CLOSE
    double lots;
    double sl;
    double tp;
    string comment;
    datetime timestamp;
};

Signal pendingSignals[];

// ─── INITIALIZATION ───────────────────────────────────────────
int OnInit() {
    // Enable web requests
    if(!TerminalInfoInteger(TERMINAL_TRADE_ALLOWED)) {
        Print("Trading not allowed!");
        return INIT_FAILED;
    }

    // Start timer for polling
    EventSetMillisecondTimer(PollIntervalMs);
    Print("Signal Receiver initialized. Polling: ", WebhookURL);
    return INIT_SUCCEEDED;
}

// ─── TIMER EVENT (POLLING) ────────────────────────────────────
void OnTimer() {
    string response = "";
    string headers = ApiKey != "" ? "X-API-Key: " + ApiKey : "";

    int result = WebRequest(
        "GET",
        WebhookURL,
        headers,
        5000,           // Timeout
        NULL, 0,        // No body for GET
        response
    );

    if(result == 200 && response != "" && response != "[]") {
        ParseSignals(response);
        ProcessSignals();
    }
}

// ─── PARSE JSON SIGNALS ───────────────────────────────────────
void ParseSignals(string json) {
    // Simple JSON parsing (production: use proper library)
    // Expected format: [{"symbol":"EURUSD","action":"BUY","lots":0.01,...}]

    // Extract each signal object
    int start = 0;
    while((start = StringFind(json, "{", start)) != -1) {
        int end = StringFind(json, "}", start);
        string obj = StringSubstr(json, start, end - start + 1);

        Signal sig;
        sig.symbol = ExtractJsonString(obj, "symbol");
        sig.action = ExtractJsonString(obj, "action");
        sig.lots = ExtractJsonDouble(obj, "lots");
        sig.sl = ExtractJsonDouble(obj, "sl");
        sig.tp = ExtractJsonDouble(obj, "tp");
        sig.comment = ExtractJsonString(obj, "comment");
        sig.timestamp = TimeCurrent();

        ArrayResize(pendingSignals, ArraySize(pendingSignals) + 1);
        pendingSignals[ArraySize(pendingSignals) - 1] = sig;

        start = end + 1;
    }
}

// ─── PROCESS SIGNALS ──────────────────────────────────────────
void ProcessSignals() {
    for(int i = 0; i < ArraySize(pendingSignals); i++) {
        Signal sig = pendingSignals[i];

        if(sig.action == "BUY") {
            ExecuteBuy(sig);
        } else if(sig.action == "SELL") {
            ExecuteSell(sig);
        } else if(sig.action == "CLOSE") {
            ClosePositions(sig.symbol);
        }

        Print("Processed: ", sig.action, " ", sig.symbol, " @ ", sig.lots, " lots");
    }

    // Clear processed
    ArrayResize(pendingSignals, 0);
}

// ─── HELPER FUNCTIONS ─────────────────────────────────────────
string ExtractJsonString(string json, string key) {
    // Extract "key":"value" from JSON
    int pos = StringFind(json, "\"" + key + "\"");
    if(pos == -1) return "";
    int start = StringFind(json, ":", pos) + 2;
    int end = StringFind(json, "\"", start);
    return StringSubstr(json, start, end - start);
}

double ExtractJsonDouble(string json, string key) {
    int pos = StringFind(json, "\"" + key + "\"");
    if(pos == -1) return 0;
    int start = StringFind(json, ":", pos) + 1;
    int end = StringFind(json, ",", start);
    if(end == -1) end = StringFind(json, "}", start);
    return StringToDouble(StringSubstr(json, start, end - start));
}

// ═══════════════════════════════════════════════════════════════
// MT5 POSITION MANAGER — Quant Prime Ascension Module (MQL5)
// Manages position lifecycle: partials, breakeven, trailing.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
input bool   EnablePartials = true;
input double TP1_Percent = 50.0;       // Close 50% at TP1
input double TP1_RR = 1.5;             // TP1 at 1.5R
input double TP2_Percent = 30.0;       // Close 30% at TP2
input double TP2_RR = 3.0;             // TP2 at 3R
input bool   MoveToBreakeven = true;   // Move SL to entry after TP1
input double BE_Offset_Pips = 1.0;     // BE offset in pips
input bool   EnableTrailing = true;
input double TrailStart_Pips = 20.0;   // Start trailing after X pips profit
input double TrailDistance_Pips = 10.0; // Trail distance

// ─── POSITION TRACKING ────────────────────────────────────────
struct ManagedPosition {
    ulong ticket;
    double entryPrice;
    double originalSL;
    double originalLots;
    bool tp1Hit;
    bool tp2Hit;
    bool atBreakeven;
};

ManagedPosition positions[];

// ─── MAIN MANAGEMENT FUNCTION ─────────────────────────────────
void ManageAllPositions() {
    for(int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if(ticket > 0) {
            ManagePosition(ticket);
        }
    }
}

void ManagePosition(ulong ticket) {
    if(!PositionSelectByTicket(ticket)) return;

    string symbol = PositionGetString(POSITION_SYMBOL);
    double entry = PositionGetDouble(POSITION_PRICE_OPEN);
    double sl = PositionGetDouble(POSITION_SL);
    double tp = PositionGetDouble(POSITION_TP);
    double lots = PositionGetDouble(POSITION_VOLUME);
    long type = PositionGetInteger(POSITION_TYPE);
    double current = type == POSITION_TYPE_BUY ? SymbolInfoDouble(symbol, SYMBOL_BID) : SymbolInfoDouble(symbol, SYMBOL_ASK);

    double pip = SymbolInfoDouble(symbol, SYMBOL_POINT) * 10;
    double risk = MathAbs(entry - sl);

    // Get or create managed position record
    int idx = FindManagedPosition(ticket);
    if(idx == -1) {
        idx = AddManagedPosition(ticket, entry, sl, lots);
    }

    // Calculate profit in R
    double profitDist = type == POSITION_TYPE_BUY ? current - entry : entry - current;
    double profitR = risk > 0 ? profitDist / risk : 0;

    // ─── PARTIAL TP1 ──────────────────────────────────────────
    if(EnablePartials && !positions[idx].tp1Hit && profitR >= TP1_RR) {
        double closeAmount = positions[idx].originalLots * (TP1_Percent / 100.0);
        if(ClosePartial(ticket, closeAmount)) {
            positions[idx].tp1Hit = true;
            Print("TP1 hit - closed ", TP1_Percent, "% at ", TP1_RR, "R");

            // Move to breakeven
            if(MoveToBreakeven && !positions[idx].atBreakeven) {
                double newSL = type == POSITION_TYPE_BUY ? 
                    entry + (BE_Offset_Pips * pip) : 
                    entry - (BE_Offset_Pips * pip);
                ModifySL(ticket, newSL);
                positions[idx].atBreakeven = true;
            }
        }
    }

    // ─── PARTIAL TP2 ──────────────────────────────────────────
    if(EnablePartials && positions[idx].tp1Hit && !positions[idx].tp2Hit && profitR >= TP2_RR) {
        double closeAmount = positions[idx].originalLots * (TP2_Percent / 100.0);
        if(ClosePartial(ticket, closeAmount)) {
            positions[idx].tp2Hit = true;
            Print("TP2 hit - closed ", TP2_Percent, "% at ", TP2_RR, "R");
        }
    }

    // ─── TRAILING STOP ────────────────────────────────────────
    if(EnableTrailing && positions[idx].tp1Hit) {
        double profitPips = profitDist / pip;
        if(profitPips >= TrailStart_Pips) {
            double trailSL = type == POSITION_TYPE_BUY ?
                current - (TrailDistance_Pips * pip) :
                current + (TrailDistance_Pips * pip);

            bool shouldModify = type == POSITION_TYPE_BUY ?
                trailSL > sl : trailSL < sl;

            if(shouldModify) {
                ModifySL(ticket, trailSL);
            }
        }
    }
}

// ─── HELPER FUNCTIONS ─────────────────────────────────────────
bool ClosePartial(ulong ticket, double lots) {
    MqlTradeRequest request = {};
    MqlTradeResult result = {};
    request.action = TRADE_ACTION_DEAL;
    request.position = ticket;
    request.volume = NormalizeDouble(lots, 2);
    request.type = PositionGetInteger(POSITION_TYPE) == POSITION_TYPE_BUY ? ORDER_TYPE_SELL : ORDER_TYPE_BUY;
    request.price = PositionGetInteger(POSITION_TYPE) == POSITION_TYPE_BUY ? SymbolInfoDouble(PositionGetString(POSITION_SYMBOL), SYMBOL_BID) : SymbolInfoDouble(PositionGetString(POSITION_SYMBOL), SYMBOL_ASK);
    return OrderSend(request, result);
}

bool ModifySL(ulong ticket, double newSL) {
    MqlTradeRequest request = {};
    MqlTradeResult result = {};
    request.action = TRADE_ACTION_SLTP;
    request.position = ticket;
    request.sl = NormalizeDouble(newSL, (int)SymbolInfoInteger(PositionGetString(POSITION_SYMBOL), SYMBOL_DIGITS));
    request.tp = PositionGetDouble(POSITION_TP);
    return OrderSend(request, result);
}

// ═══════════════════════════════════════════════════════════════
// MT5 RISK ENGINE — Quant Prime Ascension Module (MQL5)
// Position sizing, daily limits, and risk controls.
// ═══════════════════════════════════════════════════════════════

// ─── INPUTS ───────────────────────────────────────────────────
input double RiskPercent = 1.0;         // Risk per trade (%)
input double MaxDailyLossPercent = 3.0; // Max daily loss (%)
input double MaxDailyProfitPercent = 5.0; // Daily profit target (%)
input int    MaxOpenPositions = 3;      // Max simultaneous positions
input double MaxLotSize = 1.0;          // Maximum lot size
input double MinLotSize = 0.01;         // Minimum lot size
input bool   CompoundRisk = false;      // Use current balance vs starting

// ─── STATE ────────────────────────────────────────────────────
datetime lastResetDate = 0;
double dailyStartingBalance = 0;
double dailyPnL = 0;
bool dailyLimitHit = false;
bool dailyTargetHit = false;

// ─── INITIALIZATION ───────────────────────────────────────────
int OnInit() {
    ResetDailyStats();
    return INIT_SUCCEEDED;
}

void OnTick() {
    // Check for new day
    if(TimeCurrent() >= lastResetDate + 86400) {
        ResetDailyStats();
    }

    // Update daily P&L
    UpdateDailyPnL();
}

// ─── LOT SIZE CALCULATION ─────────────────────────────────────
double CalculateLotSize(string symbol, double slPips) {
    // Check if we can trade
    if(!CanOpenTrade()) return 0;

    double balance = CompoundRisk ? AccountInfoDouble(ACCOUNT_BALANCE) : dailyStartingBalance;
    double riskAmount = balance * (RiskPercent / 100.0);

    // Get pip value
    double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
    double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
    double pipValue = (tickValue / tickSize) * (SymbolInfoDouble(symbol, SYMBOL_POINT) * 10);

    // Calculate lots
    double lots = 0;
    if(slPips > 0 && pipValue > 0) {
        lots = riskAmount / (slPips * pipValue);
    }

    // Apply limits
    lots = MathMax(lots, MinLotSize);
    lots = MathMin(lots, MaxLotSize);

    // Normalize to broker step
    double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);
    lots = MathFloor(lots / lotStep) * lotStep;

    return NormalizeDouble(lots, 2);
}

// ─── CAN WE TRADE? ────────────────────────────────────────────
bool CanOpenTrade() {
    // Check daily loss limit
    if(dailyLimitHit) {
        Print("Daily loss limit hit. No new trades.");
        return false;
    }

    // Check daily profit target
    if(dailyTargetHit) {
        Print("Daily profit target hit. No new trades.");
        return false;
    }

    // Check max positions
    if(PositionsTotal() >= MaxOpenPositions) {
        Print("Max positions reached (", MaxOpenPositions, ")");
        return false;
    }

    return true;
}

// ─── DAILY P&L TRACKING ───────────────────────────────────────
void UpdateDailyPnL() {
    double currentBalance = AccountInfoDouble(ACCOUNT_BALANCE);
    double unrealizedPnL = AccountInfoDouble(ACCOUNT_PROFIT);

    dailyPnL = (currentBalance + unrealizedPnL) - dailyStartingBalance;
    double dailyPnLPercent = (dailyPnL / dailyStartingBalance) * 100;

    // Check limits
    if(dailyPnLPercent <= -MaxDailyLossPercent && !dailyLimitHit) {
        dailyLimitHit = true;
        Print("⚠️ DAILY LOSS LIMIT HIT: ", dailyPnLPercent, "%");
        CloseAllPositions();
    }

    if(dailyPnLPercent >= MaxDailyProfitPercent && !dailyTargetHit) {
        dailyTargetHit = true;
        Print("✅ DAILY PROFIT TARGET HIT: ", dailyPnLPercent, "%");
    }
}

void ResetDailyStats() {
    lastResetDate = TimeCurrent() - (TimeCurrent() % 86400); // Start of day
    dailyStartingBalance = AccountInfoDouble(ACCOUNT_BALANCE);
    dailyPnL = 0;
    dailyLimitHit = false;
    dailyTargetHit = false;
    Print("Daily stats reset. Starting balance: ", dailyStartingBalance);
}

void CloseAllPositions() {
    for(int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if(ticket > 0) {
            MqlTradeRequest request = {};
            MqlTradeResult result = {};
            PositionSelectByTicket(ticket);
            request.action = TRADE_ACTION_DEAL;
            request.position = ticket;
            request.volume = PositionGetDouble(POSITION_VOLUME);
            request.type = PositionGetInteger(POSITION_TYPE) == POSITION_TYPE_BUY ? ORDER_TYPE_SELL : ORDER_TYPE_BUY;
            request.price = PositionGetInteger(POSITION_TYPE) == POSITION_TYPE_BUY ? SymbolInfoDouble(PositionGetString(POSITION_SYMBOL), SYMBOL_BID) : SymbolInfoDouble(PositionGetString(POSITION_SYMBOL), SYMBOL_ASK);
            OrderSend(request, result);
        }
    }
}

// ─── GET CURRENT STATUS ───────────────────────────────────────
string GetRiskStatus() {
    double pnlPct = (dailyPnL / dailyStartingBalance) * 100;
    return StringFormat("P&L: %.2f%% | Limit: %.1f%% | Positions: %d/%d",
        pnlPct, MaxDailyLossPercent, PositionsTotal(), MaxOpenPositions);
}

