input color ProfitColor = clrLime;
input color LossColor = clrRed;
input int FontSize = 9;
input string FontName = "Consolas";

// ─── OBJECTS ──────────────────────────────────────────────────
string prefix = "QP_DASH_";
int lineHeight = FontSize + 6;

// ─── INITIALIZATION ───────────────────────────────────────────
int OnInit() {
    CreateDashboard();
    EventSetMillisecondTimer(500); // Update every 500ms
    return INIT_SUCCEEDED;
}

void OnDeinit(const int reason) {
    ObjectsDeleteAll(0, prefix);
}

void OnTimer() {
    UpdateDashboard();
}

// ─── CREATE DASHBOARD ─────────────────────────────────────────
void CreateDashboard() {
    int y = DashY;

    // Header
    CreateLabel(prefix + "header", "═══ QUANT PRIME ═══", DashX, y, HeaderColor);
    y += lineHeight + 4;

    // Account info
    CreateLabel(prefix + "balance_lbl", "Balance:", DashX, y, TextColor);
    CreateLabel(prefix + "balance_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    CreateLabel(prefix + "equity_lbl", "Equity:", DashX, y, TextColor);
    CreateLabel(prefix + "equity_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    // Separator
    CreateLabel(prefix + "sep1", "─────────────────────", DashX, y, HeaderColor);
    y += lineHeight;

    // Daily stats
    CreateLabel(prefix + "daily_lbl", "Daily P&L:", DashX, y, TextColor);
    CreateLabel(prefix + "daily_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    CreateLabel(prefix + "trades_lbl", "Trades:", DashX, y, TextColor);
    CreateLabel(prefix + "trades_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    CreateLabel(prefix + "winrate_lbl", "Win Rate:", DashX, y, TextColor);
    CreateLabel(prefix + "winrate_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    // Separator
    CreateLabel(prefix + "sep2", "─────────────────────", DashX, y, HeaderColor);
    y += lineHeight;

    // Open positions
    CreateLabel(prefix + "pos_lbl", "Open Pos:", DashX, y, TextColor);
    CreateLabel(prefix + "pos_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    CreateLabel(prefix + "float_lbl", "Float P&L:", DashX, y, TextColor);
    CreateLabel(prefix + "float_val", "", DashX + 80, y, TextColor);
    y += lineHeight;

    // Status
    CreateLabel(prefix + "sep3", "─────────────────────", DashX, y, HeaderColor);
    y += lineHeight;
    CreateLabel(prefix + "status_lbl", "Status:", DashX, y, TextColor);
    CreateLabel(prefix + "status_val", "", DashX + 80, y, ProfitColor);
}

void CreateLabel(string name, string text, int x, int y, color clr) {
    ObjectCreate(0, name, OBJ_LABEL, 0, 0, 0);
    ObjectSetInteger(0, name, OBJPROP_CORNER, DashCorner);
    ObjectSetInteger(0, name, OBJPROP_XDISTANCE, x);
    ObjectSetInteger(0, name, OBJPROP_YDISTANCE, y);
    ObjectSetString(0, name, OBJPROP_TEXT, text);
    ObjectSetString(0, name, OBJPROP_FONT, FontName);
    ObjectSetInteger(0, name, OBJPROP_FONTSIZE, FontSize);
    ObjectSetInteger(0, name, OBJPROP_COLOR, clr);
}

// ─── UPDATE DASHBOARD ─────────────────────────────────────────
void UpdateDashboard() {
    double balance = AccountInfoDouble(ACCOUNT_BALANCE);
    double equity = AccountInfoDouble(ACCOUNT_EQUITY);
    double floatPnL = AccountInfoDouble(ACCOUNT_PROFIT);

    // Get daily stats
    double dailyPnL = GetDailyPnL();
    int dailyTrades = GetDailyTradeCount();
    double winRate = GetDailyWinRate();

    // Update values
    ObjectSetString(0, prefix + "balance_val", OBJPROP_TEXT, DoubleToString(balance, 2));
    ObjectSetString(0, prefix + "equity_val", OBJPROP_TEXT, DoubleToString(equity, 2));
    ObjectSetInteger(0, prefix + "equity_val", OBJPROP_COLOR, equity >= balance ? ProfitColor : LossColor);

    ObjectSetString(0, prefix + "daily_val", OBJPROP_TEXT, (dailyPnL >= 0 ? "+" : "") + DoubleToString(dailyPnL, 2));
    ObjectSetInteger(0, prefix + "daily_val", OBJPROP_COLOR, dailyPnL >= 0 ? ProfitColor : LossColor);

    ObjectSetString(0, prefix + "trades_val", OBJPROP_TEXT, IntegerToString(dailyTrades));
    ObjectSetString(0, prefix + "winrate_val", OBJPROP_TEXT, DoubleToString(winRate, 1) + "%");
    ObjectSetInteger(0, prefix + "winrate_val", OBJPROP_COLOR, winRate >= 50 ? ProfitColor : LossColor);

    ObjectSetString(0, prefix + "pos_val", OBJPROP_TEXT, IntegerToString(PositionsTotal()));
    ObjectSetString(0, prefix + "float_val", OBJPROP_TEXT, (floatPnL >= 0 ? "+" : "") + DoubleToString(floatPnL, 2));
    ObjectSetInteger(0, prefix + "float_val", OBJPROP_COLOR, floatPnL >= 0 ? ProfitColor : LossColor);

    ObjectSetString(0, prefix + "status_val", OBJPROP_TEXT, TerminalInfoInteger(TERMINAL_CONNECTED) ? "CONNECTED" : "OFFLINE");
    ObjectSetInteger(0, prefix + "status_val", OBJPROP_COLOR, TerminalInfoInteger(TERMINAL_CONNECTED) ? ProfitColor : LossColor);
}

// ─── HELPER FUNCTIONS ─────────────────────────────────────────
double GetDailyPnL() {
    double pnl = 0;
    datetime dayStart = TimeCurrent() - (TimeCurrent() % 86400);
    HistorySelect(dayStart, TimeCurrent());
    for(int i = 0; i < HistoryDealsTotal(); i++) {
        ulong ticket = HistoryDealGetTicket(i);
        pnl += HistoryDealGetDouble(ticket, DEAL_PROFIT);
    }
    return pnl;
}

int GetDailyTradeCount() {
    datetime dayStart = TimeCurrent() - (TimeCurrent() % 86400);
    HistorySelect(dayStart, TimeCurrent());
    return HistoryDealsTotal();
}

double GetDailyWinRate() {
    int wins = 0, total = 0;
    datetime dayStart = TimeCurrent() - (TimeCurrent() % 86400);
    HistorySelect(dayStart, TimeCurrent());
    for(int i = 0; i < HistoryDealsTotal(); i++) {
        ulong ticket = HistoryDealGetTicket(i);
        if(HistoryDealGetInteger(ticket, DEAL_ENTRY) == DEAL_ENTRY_OUT) {
            total++;
            if(HistoryDealGetDouble(ticket, DEAL_PROFIT) > 0) wins++;
        }
    }
    return total > 0 ? (wins * 100.0 / total) : 0;
}

