// WEBHOOK BRIDGE — Quant Prime Ascension Module (Node.js)
// Receives TradingView webhooks, queues for MT5 polling.
// ═══════════════════════════════════════════════════════════════

// ─── DEPENDENCIES ─────────────────────────────────────────────
// npm install express body-parser

const express = require('express');
const app = express();
app.use(express.json());
app.use(express.text());

const PORT = 3000;
let signalQueue = [];

// ─── WEBHOOK RECEIVER ─────────────────────────────────────────
app.post('/webhook', (req, res) => {
    const signal = parseSignal(req.body);
    if (!signal) return res.status(400).json({ error: 'Invalid' });
    signal.timestamp = Date.now();
    signalQueue.push(signal);
    res.json({ success: true, queued: signalQueue.length });
});

// ─── MT5 POLLING ──────────────────────────────────────────────
app.get('/signals', (req, res) => {
    const signals = [...signalQueue];
    signalQueue = [];
    res.json(signals);
});

// ─── PARSE ALERT ──────────────────────────────────────────────
function parseSignal(body) {
    if (typeof body === 'string') {
        const parts = body.split('|');
        return { symbol: parts[0], action: parts[1], lots: parts[2] || 0.01 };
    }
    return body.symbol && body.action ? body : null;
}

app.listen(PORT, () => console.log('Bridge on port', PORT));
